create extension if not exists pgcrypto;
do $$ begin create type public.user_role as enum ('admin','caller'); exception when duplicate_object then null; end $$;
do $$ begin create type public.lead_status as enum ('new','connected','follow-up','whatsapp-details','qualified','not interested','no answer','wrong number','won','lost'); exception when duplicate_object then null; end $$;
create table if not exists public.users(id bigint generated by default as identity primary key,name text not null,email text not null unique,password_hash text not null,role public.user_role not null default 'caller',active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.batches(id bigint generated by default as identity primary key,name text not null,caller_id bigint references public.users(id) on delete set null,starts_at timestamptz,ends_at timestamptz,status text not null default 'active',created_at timestamptz not null default now());
create table if not exists public.leads(id bigint generated by default as identity primary key,lead_code text not null unique,batch_id bigint references public.batches(id) on delete set null,caller_id bigint references public.users(id) on delete set null,business_name text not null,contact_name text default '',phone text default '',category text default '',location text default '',website text default '',existing_website boolean not null default false,status public.lead_status not null default 'new',qualified boolean not null default false,follow_up_at timestamptz,notes text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.calls(id bigint generated by default as identity primary key,lead_id bigint not null references public.leads(id) on delete cascade,user_id bigint not null references public.users(id) on delete restrict,status text not null,notes text not null default '',duration_seconds integer not null default 0,called_at timestamptz not null default now());
create table if not exists public.sales(id bigint generated by default as identity primary key,lead_id bigint not null references public.leads(id) on delete restrict,caller_id bigint not null references public.users(id) on delete restrict,sale_value numeric(12,2) not null check(sale_value>=10000),stage text not null default 'won',created_at timestamptz not null default now());
create table if not exists public.payments(id bigint generated by default as identity primary key,sale_id bigint not null references public.sales(id) on delete cascade,amount numeric(12,2) not null check(amount>0),received_at timestamptz not null default now(),note text not null default '');
create table if not exists public.commission_payments(id bigint generated by default as identity primary key,caller_id bigint not null references public.users(id) on delete restrict,sale_id bigint not null references public.sales(id) on delete restrict,amount numeric(12,2) not null check(amount>0),status text not null default 'paid',paid_at timestamptz not null default now(),note text not null default '');
create index if not exists leads_caller_idx on public.leads(caller_id); create index if not exists leads_batch_idx on public.leads(batch_id); create index if not exists calls_lead_idx on public.calls(lead_id); create index if not exists sales_caller_idx on public.sales(caller_id); create index if not exists payments_sale_idx on public.payments(sale_id); create index if not exists commission_caller_idx on public.commission_payments(caller_id);
insert into public.users(name,email,password_hash,role) values('Webefy Admin','admin@webefy.in',crypt('Admin@123',gen_salt('bf')),'admin') on conflict(email) do nothing;
insert into public.users(name,email,password_hash,role) values('Demo Caller','caller@webefy.in',crypt('Caller@123',gen_salt('bf')),'caller') on conflict(email) do nothing;